('public-work-media','public-work-media',true,52428800,array['image/jpeg','image/png','image/webp','video/mp4']),
('private-original-files','private-original-files',false,209715200,null),
('private-proof-evidence','private-proof-evidence',false,209715200,null),
('profile-media','profile-media',true,10485760,array['image/jpeg','image/png','image/webp']),
