create policy public_media_read on storage.objects for select using(bucket_id in ('public-work-media','profile-media','collection-covers'));
create policy user_upload_own_folder on storage.objects for insert to authenticated with check(bucket_id in ('profile-media','collection-covers') and (storage.foldername(name))[1]=auth.uid()::text);
create policy user_update_own_folder on storage.objects for update to authenticated using(bucket_id in ('profile-media','collection-covers') and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id in ('profile-media','collection-covers') and (storage.foldername(name))[1]=auth.uid()::text);
create policy private_owner_staff_read on storage.objects for select to authenticated using(bucket_id in ('private-original-files','private-proof-evidence','temporary-uploads') and ((storage.foldername(name))[1]=auth.uid()::text or public.can_review_evidence(auth.uid())));
